export function createClient(baseUrl: string) {
  return {
    async addProduct(
      input: Product,
    ): Promise<Result<Product, CatalogError | ValidationError | TransportError>> {
      const invalid = validateAddProduct(input);
      if (invalid) return { ok: false, error: invalid };
      return request(baseUrl, "POST", "/products", { body: input });
    },

    async getProduct(sku: string): Promise<Result<Product, CatalogError | TransportError>> {
      return request(baseUrl, "GET", `/products/${encodeURIComponent(sku)}`);
    },

    async listProducts(
      tag: string | null,
      page: number,
      perPage: number,
    ): Promise<Result<Product[], ValidationError | TransportError>> {
      const invalid = validateListProducts(page, perPage);
      if (invalid) return { ok: false, error: invalid };
      return request(baseUrl, "GET", "/products", { query: { tag, page, per_page: perPage } });
    },

    async restock(
      sku: string,
      input: Restock,
    ): Promise<Result<Product, CatalogError | ValidationError | TransportError>> {
      const invalid = validateRestock(input);
      if (invalid) return { ok: false, error: invalid };
      return request(baseUrl, "PATCH", `/products/${encodeURIComponent(sku)}/stock`, {
        body: input,
      });
    },

    async priceTable(): Promise<Result<Record<string, string>, TransportError>> {
      return request(baseUrl, "GET", "/prices");
    },

    async deleteProduct(sku: string): Promise<Result<boolean, TransportError>> {
      return request(baseUrl, "DELETE", `/products/${encodeURIComponent(sku)}`);
    },

    async averageCents(skus: string): Promise<Result<number, TransportError>> {
      return request(baseUrl, "GET", "/average", { query: { skus } });
    },

    async signup(
      input: Signup,
    ): Promise<Result<Profile, UserError | ValidationError | TransportError>> {
      const invalid = validateSignup(input);
      if (invalid) return { ok: false, error: invalid };
      return request(baseUrl, "POST", "/users", { body: input });
    },

    async login(input: Signup): Promise<Result<Profile, UserError | TransportError>> {
      return request(baseUrl, "POST", "/login", { body: input });
    },

    async placeOrder(
      input: NewOrder,
    ): Promise<Result<Order, CatalogError | ValidationError | TransportError>> {
      const invalid = validatePlaceOrder(input);
      if (invalid) return { ok: false, error: invalid };
      return request(baseUrl, "POST", "/orders", { body: input });
    },

    async pay(id: number): Promise<Result<Order, CatalogError | TransportError>> {
      return request(baseUrl, "POST", `/orders/${id}/pay`);
    },

    async summaries(): Promise<Result<Summary[], TransportError>> {
      return request(baseUrl, "GET", "/summaries");
    },

    async openCount(email: string): Promise<Result<number, TransportError>> {
      return request(baseUrl, "GET", "/orders/open", { query: { email } });
    },

    async customers(): Promise<Result<[string, number][], TransportError>> {
      return request(baseUrl, "GET", "/customers");
    },

    async firstEmail(): Promise<Result<string | null, TransportError>> {
      return request(baseUrl, "GET", "/orders/first");
    },
  };
}
