import { createClient } from "../canon/client";
import type { Order } from "../canon/types";
import type { Outcome } from "./result";

/** Get one page of a customer's orders, oldest first. */
export async function listOrders(
  baseUrl: string,
  email: string,
  page: number,
  perPage: number,
): Promise<Outcome<Order[]>> {
  if (!Number.isSafeInteger(page) || !Number.isSafeInteger(perPage)) {
    return { ok: false, error: { kind: "ValidationError" } };
  }
  return createClient(baseUrl).listOrders(email, page, perPage);
}
