import type { Order as WireOrder } from "../canon/types";
import type { Outcome } from "./result";

export type Order = Omit<WireOrder, "status"> & { status: "open" | "paid" | "cancelled" };

/** Narrow Canon's wire string to the supported order statuses. */
export function orderOutcome(outcome: Outcome<WireOrder>): Outcome<Order> {
  if (!outcome.ok) return outcome;

  const status = outcome.value?.status;
  if (status === "open" || status === "paid" || status === "cancelled") {
    return { ok: true, value: { ...outcome.value, status } };
  }
  return { ok: false, error: { kind: "TransportError" } };
}
